"""Save exact next built-in generation requests without resetting any artwork."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];G=R/'sprite-fighter';jobs=[]
for slug in ['naruto','saitama']:
 a=G/'characters'/slug/'art/comic-style-v10';qs=json.loads((a/'requests.json').read_text(encoding='utf-8'))
 for q in qs:
  if (a/(q['kind']+'.generation.json')).exists():continue
  refs=[q['references'][0],str(a/(q['form']+'-00.png'))]
  prompt=q['prompt']+''' Image2 is approved LINEWORK, CHARACTER AND ANATOMY reference ONLY, never its pose layout. Image1 is the exact cell-by-cell content authority. Preserve EVERY figure and effect in original order. Source cells showing only chakra fists, black/purple spheres, smear trails, body fragments or other graphics MUST remain those fragments/effects; DO NOT invent a person in those cells. Cell-specific costume/form changes are intentional, including base clothes in a gold-form sheet: copy each cell's actual clothing/colors. Human Naruto has SHORT SPIKY hair, with just TWO THIN narrow cloth headband ties, never a flowing mane. Humans have long limbs and modest head size. Saitama has tiny BLACK pupils in simple white eyes, no colored irises, with deadpan calm expressions. Gold forms use flat gold and one hard ochre shadow, without glossy texture, soft halos or extra sparks. Preserve creature tail counts and white skeletal armor. Keep chakra arm extensions only where pictured. Remove any solid green rectangular source background. Empty final cells stay empty. True transparent background; wide gutters; no clipped parts.'''
  jobs.append(dict(slug=slug,kind=q['kind'],prompt=prompt,referenced_image_paths=refs,transparent_background=True,destination=q['destination'],count=q['count'],columns=q['columns'],rows=q['rows']))
 for kind,prompt in [('portrait','Create one transparent game HUD portrait of '+('Naruto Uzumaki, short spiky blond hair, blue eyes, three whisker marks on each cheek, leaf forehead protector on black cloth, orange-black Shippuden jacket, determined youthful face.' if slug=='naruto' else 'Saitama, bald oval head, tiny BLACK dot pupils in simple WHITE oval eyes, deadpan relaxed face, adult lean neck, yellow suit collar and white cape with round dark clasps.')+' Match supplied illustrated atlas style. Head and upper shoulders, three-quarter view looking right, level chin, entire hair/head/shoulders inside frame with generous transparent margins. Crisp economical comic ink, broad flat colors and ONE hard shadow; no gradients, shine, ornaments, text, scenery, circular badge or extra portraits. True transparent background.')]:
  if not (a/(kind+'.png')).exists():jobs.append(dict(slug=slug,kind=kind,prompt=prompt,referenced_image_paths=[str(a/('base-00.png' if slug=='naruto' else 'hero-00.png'))],transparent_background=True,destination=str(a/(kind+'.png')),asset_type='portrait'))
report=dict(status='Pending built-in generator reset; do not use paid API fallback',reset_epoch=1792672252,tool='image_gen.imagegen',jobs=jobs)
(G/'comic-style-v10/resume-requests.json').write_text(json.dumps(report,indent=2),encoding='utf-8');print('Resume requests saved:',len(jobs),'assets; exact prompts and references retained.')
